import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
import {PythonSession} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/index.ts';
const rows=[];
for(const prefix of ['', '# coding: utf8\n', '# coding: utf-8\n', '# coding: latin1\n', '# coding: ascii\n', '\xef\xbb\xbf']) {
 for(const body of ['# \xff', '# \xc3', '# \xc3\xa9\xff', '# \xf0\x9f\x90\x8d\xff', '\n#\xff', '\r#\xff', '\r\n#\xff', '#\x00', "x='\x00'", "x='\xff'", '# coding: ascii', '# coding: latin-1', '# coding: utf8']) {
  for(const ending of ['', '\n']) {
   const data=prefix+body+ending;
   const literal="b'"+Array.from(data,c=>'\\x'+c.charCodeAt(0).toString(16).padStart(2,'0')).join('')+"'";
   const source=`try:\n    compile(${literal}, 'edge.py', 'exec')\nexcept SyntaxError as e:\n    print(e.args, e.filename, e.lineno, e.offset, e.end_lineno, e.end_offset, repr(e.text))\nelse:\n    print('ok')\n`;
   const oracle=spawnSync('/opt/homebrew/bin/python3.14',['-I','-c',source],{encoding:'utf8'});
   let output='';
   const session=new PythonSession({hashSeed:[1n,2n],limits:{maxDepth:100,maxSteps:1000000,maxAllocatedBytes:16000000},output:{write(t){output+=t},flush(){}}});
   const result=session.exec(source);
   rows.push({data,source,oracle:{stdout:oracle.stdout,stderr:oracle.stderr,status:oracle.status},output,status:result.status,matches:result.status==='ok'&&output===oracle.stdout});
  }
 }
}
writeFileSync('/tmp/source-codec-audit.json',JSON.stringify(rows,null,2));
console.log(rows.length,rows.filter(x=>!x.matches));

